+.allocation-total span, .allocation-total small { display: block; color: var(--muted); font-size: 0.72rem; }
+.allocation-total strong { display: block; margin: 3px 0; font-family: 'Newsreader', serif; font-size: 1.75rem; }
+.envelope-groups { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; margin-top: 30px; }
+.envelope-group { padding: 20px; border: 1px solid var(--line); border-radius: 6px; background: rgba(251, 252, 248, 0.96); }
+.group-heading { display: grid; grid-template-columns: 10px 1fr auto; gap: 9px; align-items: center; margin-bottom: 10px; }
+.group-heading h2 { margin: 0; font-family: 'Newsreader', serif; font-size: 1.2rem; }
+.group-heading small { color: var(--muted); font-weight: 700; }
+.group-dot { width: 8px; height: 8px; border-radius: 50%; }
+.group-dot.needs { background: var(--forest); }
+.group-dot.wants { background: var(--coral); }
+.group-dot.savings { background: var(--gold); }
+.envelope-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 11px 0; border-top: 1px solid #e4e7e1; }
+.envelope-row > span { min-width: 0; font-size: 0.8rem; }
+.envelope-row > div { display: flex; width: 92px; align-items: center; padding: 5px 7px; border: 1px solid #ccd3cc; border-radius: 3px; background: #fff; }
+.envelope-row > div span { color: var(--muted); font-size: 0.75rem; }
+.envelope-row input { width: 100%; min-width: 0; border: 0; outline: 0; text-align: right; }
+.save-message { display: flex; gap: 7px; align-items: center; margin: 17px 0 -12px; font-size: 0.82rem; font-weight: 700; }
+.save-message.success { color: var(--forest); }
+.save-message.error { color: #a43e31; }
+.mobile-brand { display: none; }
+
