+using System.Text.Json;
+using Backend.Data;
+using Microsoft.AspNetCore.Mvc;
+using Microsoft.EntityFrameworkCore;
+
+namespace Backend.Controllers;
+
+[ApiController]
+[Route("api/prototype")]
+public sealed class PrototypeController(BudgetDbContext database) : ControllerBase
+{
+    [HttpGet]
+    public async Task<IActionResult> Get(CancellationToken cancellationToken)
+    {
+        await using var command = database.Database.GetDbConnection().CreateCommand();
+        command.CommandText = "SELECT data FROM prototype_state WHERE id = 1";
+        await database.Database.OpenConnectionAsync(cancellationToken);
+        var result = await command.ExecuteScalarAsync(cancellationToken);
+
+        return result is string data
+            ? Content(data, "application/json")
+            : NotFound();
+    }
+
+    [HttpPut]
+    public async Task<IActionResult> Save(JsonElement state, CancellationToken cancellationToken)
+    {
+        if (state.ValueKind is not JsonValueKind.Object)
+        {
+            return BadRequest(new ProblemDetails { Detail = "Prototype state must be a JSON object." });
+        }
+
+        await database.Database.ExecuteSqlInterpolatedAsync($"""
+            INSERT INTO prototype_state (id, data, updated_at)
+            VALUES (1, {state.GetRawText()}, {DateTimeOffset.UtcNow.ToString("O")})
+            ON CONFLICT(id) DO UPDATE SET
+                data = excluded.data,
+                updated_at = excluded.updated_at;
+            """, cancellationToken);
+
+        return Ok(state);
+    }
+}
*** End Patch"}

